import math

def det(mat):
    """求二阶矩阵行列式"""
    return mat[0][0] * mat[1][1] - mat[0][1] * mat[1][0]

def adj(mat):
    mat[0][0] , mat[1][1]= mat[1][1] , mat[0][0]
    mat[0][1] *= -1
    mat[1][0] *= -1
    return mat

def mul(a, b, x, y, z): # 矩阵乘法，a*b，其中 x,y,z 为尺寸参数
    c = [[0] * z for _ in range(x)]
    for i in range(x):
        for j in range(z):
            for k in range(y):
                c[i][j] += a[i][k] * b[k][j]
            c[i][j] %= 256
    return c

def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    else:
        g, x, y = extended_gcd(b % a, a)
        return g, y - (b // a) * x, x

def modinv(a, m):
    g, x, y = extended_gcd(a, m)
    if g != 1:
        raise Exception("模逆不存在")
    return x % m

def I_k(m):
    I = [[0 for _ in range(3)] for _ in range(3)]
    for i in range(3):
        I[i][i] = m
    return I

def rev(mat):
    mat = mul(I_k(modinv((det(mat) & 0xFF), 0xFF))) ,adj(mat)

